'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var tryRequire = require( '@stdlib/utils/try-require' );
var factory = require( './../lib/factory.js' );
var eligible = require( './../lib/can_use_native.js' );
var base = require( './../lib/base.js' );
var run = require( './helpers.js' ).run;


// VARIABLES //

var addon = tryRequire( resolve(__dirname, '../src/addon.node') );
var opts = {
	'skip': (addon instanceof Error)
};


// TESTS //

tape( 'main export is a function', opts, function test(t) {
	t.ok( true, __filename );
	t.strictEqual(typeof addon, 'function', 'actual addon');
	t.end();
});
tape( 'dpbequ: compiled native reference and storage regressions', opts, function test(t) {
	var calls = 0;
	var f;
	f = factory(function backend() {
		calls += 1;
		return addon.apply(null, arguments);
	}, eligible, base);
	run(t, f);
	t.strictEqual(calls, 768, 'every ordinary reference fixture actually dispatches native');
	t.end();
});
tape( 'dpbequ: independent raw argument protocol before mutation', opts, function test(t) {
	var args;
	var sc;
	var am;
	sc = new Float64Array([91]);
	am = new Float64Array([92]);
	args = [122, 0, 0, null, null, null, null, null, null, null, sc, 0, am, 0];
	t.throws(function bad() {
		addon.apply(null, args.slice(0, 13));
	}, RangeError, 'missing raw argument rejected');
	t.throws(function bad() {
		addon.apply(null, args.concat([1]));
	}, RangeError, 'extra raw argument rejected');
	t.strictEqual(sc[0], 91, 'rejections preserve SCOND');
	t.strictEqual(am[0], 92, 'rejections preserve AMAX');
	t.strictEqual(addon.apply(null, args), 0, 'raw empty ignores inactive metadata');
	t.strictEqual(sc[0], 1, 'empty SCOND');
	t.strictEqual(am[0], 0, 'empty AMAX');
	t.end();
});
